import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status: string, authorized: number, captured = 0, refunded = 0, requests = 1) => ({ status, authorized, captured, refunded, requests });

test('authorize, approve, capture, refund', async () => {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.deepEqual(await h.payment('p'), view('authorizing', 2));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'card.authorize');
  assert.equal(effs[0].from, 'p');
  assert.deepEqual(effs[0].data, { amount: 2 });
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.payment('p'), view('authorized', 2));
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.equal((await h.void('p')).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), view('captured', 2, 2, 1));
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), view('refunded', 2, 2, 2));
  assert.equal((await h.refund('p', 1)).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  assert.equal((await h.authorize('p', 3)).ok, false);
  assert.equal(await h.payment('p'), null);
  assert.equal((await h.authorize('p', 0)).ok, false);
  assert.equal((await h.capture('q', 1)).ok, false);
  assert.equal((await h.timedOut('q')).ok, false);
  assert.equal(await h.payment('q'), null);
  assert.deepEqual(await h.authorize('p', 1), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.capture('p', 1)).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.deepEqual(await h.void('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), view('voided', 1));
  assert.equal((await h.capture('p', 1)).ok, false);
});

test('timeouts and late answers', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.pendingEffects()).length, 3);
  assert.deepEqual(await h.payment('p'), view('authorizing', 1, 0, 0, 3));
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), view('failed', 1, 0, 0, 3));
  assert.equal((await h.timedOut('p')).ok, false);
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 3);
  await h.completeEffect(effs[0].id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('increase', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.increase('q')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), view('authorized', 3));
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.capture('p', 4)).ok, false);
  assert.deepEqual(await h.capture('p', 3), { ok: true });
  assert.equal((await h.increase('p')).ok, false);
  assert.deepEqual(await h.payment('p'), view('captured', 3, 3));
  assert.deepEqual(await h.refund('p', 2), { ok: true });
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), view('refunded', 3, 3, 3));
});

test('capture within the raised amount', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.deepEqual(await h.payment('p'), view('captured', 2, 2));
});

test('expire', async () => {
  const h = await createHost();
  assert.equal((await h.expire('p')).ok, false);
  await h.authorize('p', 1);
  assert.equal((await h.expire('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  await h.increase('p');
  assert.deepEqual(await h.expire('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), view('expired', 2));
  for (const r of [await h.capture('p', 1), await h.void('p'), await h.increase('p'), await h.expire('p'),
    await h.refund('p', 1), await h.timedOut('p'), await h.authorize('p', 1)]) assert.equal(r.ok, false);
  assert.deepEqual(await h.payment('p'), view('expired', 2));

  await h.authorize('c', 2);
  const [f] = await h.pendingEffects();
  await h.completeEffect(f.id, 'ok');
  await h.capture('c', 1);
  assert.equal((await h.expire('c')).ok, false);
  assert.equal((await h.payment('c'))!.status, 'captured');
});

test('first answer decides', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(b.id, 'failed');
  assert.equal((await h.payment('p'))!.status, 'declined');
  await h.completeEffect(a.id, 'ok');
  assert.deepEqual(await h.payment('p'), view('declined', 2, 0, 0, 2));
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.capture('p', 1)).ok, false);
});
